   "lead": "Un nuovo video promozionale del film «The Apothecary Diaries: The Late Lady's Treasure» ha rivelato l'ingresso nel cast delle doppiatrici Miyuki Sawashiro e Ai Mikami, che interpreteranno rispettivamente i personaggi di Ruoqing e Yinshan. Il filmato presenta i due nuovi personaggi in vista dell'uscita del film, inedito capitolo cinematografico della serie, prevista nelle sale giapponesi l'11 dicembre.",
