   "orig": "Trump takes credit for a new ‘golden age’ of U.S. science",
   "lead": "Il presidente Donald Trump ha rivendicato il merito di una nuova «età dell'oro» della scienza statunitense, in occasione della consegna delle prime medaglie nazionali per la scienza assegnate direttamente dal presidente a figure di spicco dell'industria tecnologica. L'iniziativa, descritta come un approccio non convenzionale, ha visto Trump premiare pesi massimi del settore tech, suscitando sia entusiasmo sia scetticismo sulla reale efficacia di questa alleanza con i grandi nomi della Silicon Valley.",
