   "lead": "Raju, fondatore della Nagarjuna Construction Company e insignito del premio Padma Shri, una delle più alte onorificenze civili indiane. Raju è stato una figura di rilievo nel settore delle costruzioni in India, avendo fondato una delle principali società di ingegneria e infrastrutture del Paese. Lo riferisce The Hindu.",
