   "orig": "Satellite cinese “insegue” quello tedesco: “Così Pechino spia l’esercito di Berlino”",
   "lead": "Secondo quanto riportato, un satellite spia cinese di tipo TJS-20 si sarebbe avvicinato e inseguito un satellite Inmarsat, utilizzato anche per le comunicazioni delle forze armate tedesche. Inmarsat è una società britannica diventata nel 2023 sussidiaria della statunitense Viasat, che gestisce una flotta di oltre una dozzina di satelliti, prevalentemente geostazionari. Lo riferisce Il Fatto Quotidiano.",
   "more": [
    "I satelliti geostazionari orbitano alla stessa velocità di rotazione della Terra, rimanendo fissi sopra un punto del pianeta: sono usati soprattutto per telecomunicazioni e osservazione, e il loro avvicinamento reciproco può essere interpretato come attività di sorveglianza o spionaggio."
   ],
