   "sez": "cultura",
   "titolo": "A Kathmandu cresce il traffico per l'esodo delle festività di Dashain",
   "orig": "Dashain travel rush builds, with traffic jams on some routes",
   "lead": "Nella valle di Kathmandu si registra un intenso afflusso di persone che lasciano la città per raggiungere le proprie zone d'origine in occasione delle festività di Dashain, una delle ricorrenze più importanti del Nepal. La polizia segnala ingorghi su alcune strade e dichiara di stare gestendo la situazione, mentre gli operatori del trasporto lamentano che le ripetute chiusure stradali stanno creando disagi ai viaggiatori durante l'esodo festivo. Lo riferisce The Kathmandu Post.",
   "more": [
    "Dashain è la principale festività induista nepalese, celebrata ogni anno con un lungo periodo di festeggiamenti durante il quale molti abitanti delle città tornano nei villaggi d'origine per riunirsi con le famiglie, generando tradizionalmente un forte aumento del traffico sulle strade del Paese."
   ],
