   "id": "z4a7291b8",
   "sez": "sport",
   "titolo": "La federcalcio sudcoreana condanna gli attacchi personali contro i giocatori della nazionale",
   "orig": "South Korean FA condemns ‘personal attacks, criticism’ of players as attempt to sow discord",
   "lead": "La federazione calcistica della Corea del Sud ha invitato i tifosi a cessare gli «eccessivi attacchi personali» nei confronti dei calciatori della nazionale, avvertendo del «peso psicologico» che tali critiche possono infliggere ai giocatori finiti nel mirino dopo la deludente eliminazione ai Mondiali. L'allenatore Hong Myung-bo si è dimesso dopo che la squadra non è riuscita a superare la fase a gironi in Nord America, mentre il tecnico ad interim spagnolo Robert Moreno attende di sapere se il suo incarico sarà prorogato. La nazionale è sotto pressione anche in vista della Coppa d'Asia, in programma a gennaio in Arabia Saudita. Lo riferisce il South China Morning Post.",
   "more": [
    "La Coppa d'Asia è il principale torneo calcistico continentale per nazionali asiatiche; la Corea del Sud è una delle squadre storicamente più competitive del continente, e un cattivo risultato mondiale genera spesso forti pressioni mediatiche e sui social sui giocatori coinvolti."
   ],
