   "id": "za83ee72b",
   "sez": "prima",
   "titolo": "Papa Leone XIV: confermato il cancro al polmone, l'intervento al Gemelli è riuscito",
   "orig": "Pope Leo has cancerous tumour removed in lung operation",
   "lead": "Il Vaticano ha confermato che il nodulo rimosso martedì pomeriggio dal polmone destro di Papa Leone XIV, 71 anni, era un tumore maligno. L'intervento, durato circa novanta minuti al Policlinico Gemelli di Roma, ha comportato l'asportazione del lobo inferiore del polmone destro e si è concluso positivamente. Una fonte vaticana ha precisato che sono in corso ulteriori accertamenti per stabilire se il tumore si sia esteso ad altre parti del corpo. Il nodulo era stato individuato durante un controllo medico di routine nelle settimane precedenti.",
   "more": [
    "Il Policlinico Gemelli è da decenni l'ospedale di riferimento dei pontefici: vi fu ricoverato a lungo anche Papa Francesco nel 2025, poco prima di morire. Leone XIV, al secolo Robert Francis Prevost, primo papa statunitense della storia, è stato eletto l'8 maggio 2025."
   ],
