   "sez": "prima",
   "titolo": "Yemen, missili intercettati vicino a Riad dopo il raid saudita su un deposito di carburante Houthi",
   "orig": "Missiles intercepted near Riyadh after Saudi coalition hits Yemen fuel depot",
   "lead": "La coalizione a guida saudita impegnata in Yemen ha colpito un deposito di carburante vicino a Sanaa, la capitale controllata dai ribelli Houthi. In risposta, missili lanciati verso l'Arabia Saudita sono stati intercettati nei pressi di Riad; secondo fonti locali alcuni detriti caduti hanno ferito almeno quattro persone nella capitale saudita. Negli ultimi giorni gli Houthi hanno intensificato gli attacchi con missili e droni contro il Regno, alimentando il timore di un'escalation nella regione.",
   "more": [
    "Il direttore del Fondo monetario internazionale, Kristalina Georgieva, ha avvertito che gli attacchi contro l'Arabia Saudita, primo esportatore mondiale di petrolio, rischiano di avere ripercussioni sull'economia globale."
   ],
