   "id": "z4f0f7a26",
   "sez": "italia",
   "titolo": "«Aura Battle», la sfida social che impazza a San Lorenzo e tormenta i residenti del quartiere romano",
   "orig": "Aura Battle, cos'è la sfida che impazza a San Lorenzo e tormenta i residenti: «Musica e caos fino a notte fonda»",
   "lead": "Nato in Sud America e diffuso rapidamente in Europa, il fenomeno social dell'«Aura Battle» è arrivato a Roma dopo aver già conquistato Milano. Gruppi di giovani si sfidano a colpi di musica ad alto volume e coreografie improvvisate, riprese e condivise sui social, nel quartiere di San Lorenzo. I residenti lamentano schiamazzi e musica fino a notte fonda, mentre il fenomeno continua a diffondersi di quartiere in quartiere. Lo riferisce Il Messaggero – Roma.",
   "more": [
    "Le sfide social di questo tipo, spesso nate su piattaforme come TikTok, si diffondono rapidamente da una città all'altra grazie all'emulazione tra gruppi di giovani, generando periodicamente tensioni con i residenti dei quartieri coinvolti."
   ],
