   "sez": "economia",
   "titolo": "Singapore, il Pil cresce oltre il 5% nel terzo trimestre grazie al boom dell'intelligenza artificiale",
   "orig": "Singapore’s economy grows more than 5 percent amid AI boom",
   "lead": "L'economia di Singapore è cresciuta del 5,4% su base annua nel trimestre luglio-settembre, secondo le stime preliminari del governo della città-Stato. L'espansione è trainata soprattutto dal settore tecnologico e dagli investimenti legati all'intelligenza artificiale, che stanno sostenendo la domanda di semiconduttori e servizi digitali nell'intera regione asiatica.",
   "more": [
    "Singapore si è posizionata come uno dei principali snodi regionali per gli investimenti nell'intelligenza artificiale, attirando centri dati e sedi asiatiche di grandi aziende tecnologiche internazionali."
   ],
