   "lead": "Il pilota da caccia ceco Aleš Svoboda si sta addestrando per pilotare una capsula SpaceX diretta verso la Stazione spaziale internazionale nel 2027, in attesa dell'approvazione definitiva della missione. Sarebbe uno dei primi cechi a volare nello spazio dai tempi della missione del cosmonauta Vladimír Remek nel 1978. Lo riferisce Expats.cz.",
