   "lead": "Il Bhutan ha registrato a settembre un aumento degli arrivi turistici superiore al 28% rispetto allo stesso mese dello scorso anno, secondo il bollettino mensile del Dipartimento del Turismo. Anche le entrate derivanti dalla tassa per lo sviluppo sostenibile, pagata da ogni visitatore straniero, sono cresciute di oltre il 22%.",
