   "lead": "Shohin Airlines, nuova compagnia aerea privata del Tagikistan con ambizioni regionali, ha presentato il suo primo velivolo ad ala fissa. Si tratta della prima compagnia privata del Paese centroasiatico a dotarsi di una flotta propria, in un mercato finora dominato dal vettore di bandiera statale.",
