   "titolo": "Negli Usa i college lanciano nuovi corsi di laurea per il mercato del lavoro che cambia",
   "orig": "How colleges are creating programs for a changing U.S. job market",
   "lead": "Cosa hanno in comune l'influencer marketing, l'intelligenza artificiale e le scienze della salute? Sono tutti ambiti per cui le università statunitensi hanno lanciato negli ultimi anni nuovi corsi di laurea, nel tentativo di intercettare studenti in cerca di percorsi professionali più legati alle trasformazioni del mercato del lavoro. Lo riferisce NPR – Istruzione.",
   "more": [
    "La nascita di nuovi corsi di laurea legati a professioni emergenti riflette quanto velocemente stia cambiando il mondo del lavoro, spingendo gli atenei a ripensare offerta didattica e sbocchi professionali tradizionali."
   ],
