   "titolo": "La Polonia lancia l'allarme: «Mosca è pronta a sferrare un attacco ibrido letale»",
   "orig": "La Polonia lancia l'allarme: \"Mosca vuole sferrare un attacco ibrido letale\"",
   "lead": "Il ministro degli Esteri polacco Radoslaw Sikorski ha lanciato un nuovo allarme sul rischio di un attacco ibrido «letale» da parte della Russia contro la Polonia e i suoi alleati, ponendo con forza il tema di come reagire. Il primo ministro Donald Tusk ha chiesto nuovi strumenti di difesa in vista del prossimo Consiglio europeo, in un clima di tensione crescente lungo il fianco orientale della Nato. Lo riferisce la Repubblica.",
   "more": [
    "La sicurezza in Europa resta segnata da crescenti tensioni legate al conflitto in Ucraina, con ripetute indagini su episodi di sabotaggio alle infrastrutture critiche e sorvoli di droni non identificati sui Paesi baltici e sulla Polonia nelle ultime settimane.",
    "Anche il capo del servizio di sicurezza interno britannico MI5 ha ribadito nei giorni scorsi che la Russia resta la minaccia più grave per il Regno Unito, citando le crescenti attività di sabotaggio e spionaggio attribuite a Mosca in Europa."
   ],
