   "sez": "mondo",
   "titolo": "Gli Stati Uniti inseriscono la Nigeria tra i Paesi che consentono il reclutamento di bambini soldato",
   "orig": "Nigeria: U.S. Places Nigeria Among Countries Allowing Recruitment of Child Soldiers",
   "lead": "Gli Stati Uniti hanno inserito la Nigeria nella lista dei Paesi che permettono il reclutamento di minori nei conflitti armati, un passaggio che mette ulteriore pressione sul governo di Abuja affinché affronti il problema e dimostri il rispetto degli standard internazionali per la protezione dell'infanzia nei conflitti. Lo riferisce allAfrica.",
   "more": [
    "Il nord-est della Nigeria è teatro da oltre un decennio del conflitto con il gruppo armato Boko Haram e le sue scissioni, in cui l'arruolamento di minori tra i combattenti è stato più volte documentato da organizzazioni umanitarie internazionali. Lo riferisce allAfrica."
   ],
