   "sez": "mondo",
   "titolo": "Cina, un gruppo navale con portaerei inviato nel Pacifico occidentale",
   "orig": "China sends aircraft carrier group into western Pacific",
   "lead": "Pechino ha inviato un gruppo navale imperniato su una portaerei nelle acque del Pacifico occidentale, descrivendo le manovre come esercitazioni «realistiche» non dirette contro nessun Paese o obiettivo specifico. Il Giappone, che segue con attenzione i movimenti della Marina cinese nella regione, osserva da vicino l'operazione. Lo riferisce The Japan Times.",
   "more": [
    "La Cina ha ampliato negli ultimi anni la propria capacità navale di proiezione, aumentando la frequenza delle esercitazioni nel Pacifico occidentale in un contesto di crescente tensione con Giappone, Taiwan e Stati Uniti nella regione indo-pacifica."
   ],
