   "sez": "mondo",
   "titolo": "Pakistan, la provincia di Khyber Pakhtunkhwa sotto stato d'emergenza: scontro tra governo e opposizione",
   "orig": "‘Emergency applies to all of KP, not just 12 districts’",
   "lead": "Il governo pakistano ha imposto lo stato d'emergenza e il governo del governatore in tutta la provincia di Khyber Pakhtunkhwa, non solo nei dodici distretti più colpiti dal terrorismo, ha precisato il ministro della Giustizia Azam Nazeer Tarar. Per quei distretti è stato istituito un segretariato dedicato con misure straordinarie. L'opposizione, riunita in un incontro congiunto, ha chiesto l'immediato ritiro dell'emergenza, denunciando la rimozione del governo eletto della provincia e l'arresto di esponenti e militanti politici.",
   "more": [
    "Il Khyber Pakhtunkhwa, provincia di confine con l'Afghanistan, è da anni tra le aree del Pakistan più colpite dagli attacchi di gruppi armati legati ai talebani pakistani; il governo centrale ha invocato l'articolo 232 della Costituzione, che consente l'imposizione dell'emergenza in caso di grave minaccia alla sicurezza."
   ],
