   "id": "zc6f24da9",
   "sez": "mondo",
   "titolo": "Costa Rica apre una mega-prigione ispirata al modello salvadoregno",
   "orig": "Costa Rica opent in navolging van El Salvador strenge megagevangenis",
   "lead": "Il Costa Rica ha inaugurato una nuova mega-prigione da oltre 5.000 posti ad Alajuela, a mezz'ora dalla capitale San José, concepita esplicitamente sul modello del famoso Cecot salvadoregno, la struttura da 40.000 detenuti voluta dal presidente Nayib Bukele. Lo stesso Bukele ha posato la prima pietra dell'edificio costaricano e ha partecipato all'inaugurazione, segno di una crescente influenza del modello salvadoregno di «mano dura» contro il crimine organizzato in America centrale. Lo riferisce NOS.",
   "more": [
    "Il modello carcerario salvadoregno, basato su detenzioni di massa e condizioni molto rigide, è stato più volte criticato dalle organizzazioni per i diritti umani, ma continua a essere guardato con interesse da altri governi della regione alle prese con l'espansione delle organizzazioni criminali."
   ],
