   "sez": "ambiente",
   "titolo": "Fiji, l'inviato per l'oceano porterà le preoccupazioni del Pacifico alla COP31",
   "orig": "Ocean concerns to be taken to COP31",
   "lead": "L'inviato del Pacifico per l'oceano, Inia Seruiratu, ha dichiarato che proteggere l'oceano è essenziale per la sicurezza alimentare, i mezzi di sussistenza e l'identità culturale delle comunità del Pacifico, e porterà queste istanze alla prossima conferenza Onu sul clima, la COP31. Secondo Seruiratu l'oceano non è solo una risorsa naturale, ma un elemento centrale per la sicurezza economica e la vita quotidiana delle isole del Pacifico, già colpite dagli effetti del cambiamento climatico. Lo riferisce FBC News.",
   "more": [
    "Le piccole isole del Pacifico sono tra i territori più esposti all'innalzamento del livello del mare e ai fenomeni climatici estremi, pur contribuendo in misura minima alle emissioni globali di gas serra."
   ],
