     "t": "Riprendendo BBC, cita la frase di Patel sulla 'tecnologia di super-intelligenza' dell'azienda come oggetto delle intercettazioni e riporta le possibili pene: cinque anni di carcere, multa di 250.000 dollari e tre anni di libertà vigilata.",
     "b": "a"
